import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionUser = (String) req.getSession().getAttribute("username");
        if (sessionUser == null) {
            resp.sendError(401, "Not authenticated");
            return;
        }

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String department = req.getParameter("dept");

        // Input length validation
        if (reportType == null || reportType.length() > 50) {
            resp.sendError(400, "Invalid report type");
            return;
        }
        if (dateFrom != null && !dateFrom.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }
        if (dateTo != null && !dateTo.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build query based on report type
        StringBuilder query = new StringBuilder();
        query.append("SELECT r.id, r.title, r.created_at, r.data ");
        query.append("FROM reports r INNER JOIN departments d ON r.dept_id = d.id ");
        query.append("WHERE r.report_type = '").append(reportType).append("' ");

        if (dateFrom != null) {
            query.append("AND r.created_at >= '").append(dateFrom).append("' ");
        }
        if (dateTo != null) {
            query.append("AND r.created_at <= '").append(dateTo).append("' ");
        }
        if (department != null && !department.isEmpty()) {
            // Department uses parameterized approach via allowlist
            query.append("AND d.name = '").append(sanitizeDept(department)).append("' ");
        }
        query.append("AND r.owner = '").append(sessionUser).append("' ");
        query.append("ORDER BY r.created_at DESC LIMIT 100");

        log.info("Report query for user " + sessionUser + ": type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"date\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String sanitizeDept(String dept) {
        // Remove obvious SQL keywords but this is NOT sufficient protection
        return dept.replaceAll("(?i)(union|select|drop|insert|update|delete|;|--)", "");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.sendError(405, "Method not allowed");
    }
}
